from fractions import Fraction

# Exact polynomials in the independent variables a, b, c.
# Coordinates: H=(0,0), A=(-a,0), B=(0,b), C=(c,0).
# Here a,b,c>0; ac<b^2 additionally makes the triangle acute.
class P:
    def __init__(self, value=0):
        if isinstance(value, P):
            self.terms = value.terms.copy()
        elif isinstance(value, dict):
            self.terms = {k: v for k, v in value.items() if v}
        else:
            self.terms = {(0, 0, 0): value} if value else {}

    def __add__(self, other):
        other = P(other)
        result = self.terms.copy()
        for k, v in other.terms.items():
            result[k] = result.get(k, 0) + v
        return P(result)

    __radd__ = __add__

    def __neg__(self):
        return P({k: -v for k, v in self.terms.items()})

    def __sub__(self, other):
        return self + (-P(other))

    def __rsub__(self, other):
        return P(other) - self

    def __mul__(self, other):
        other = P(other)
        result = {}
        for k, v in self.terms.items():
            for j, w in other.terms.items():
                exponent = tuple(x + y for x, y in zip(k, j))
                result[exponent] = result.get(exponent, 0) + v * w
        return P(result)

    __rmul__ = __mul__

    def __pow__(self, n):
        result = P(1)
        for _ in range(n):
            result = result * self
        return result

    def is_zero(self):
        return not self.terms


a = P({(1, 0, 0): 1})
b = P({(0, 1, 0): 1})
c = P({(0, 0, 1): 1})
zero = P(0)

def sub(u, v):
    return tuple(x - y for x, y in zip(u, v))

def dot(u, v):
    return sum(x * y for x, y in zip(u, v))

def norm2(u):
    return dot(u, u)

def det(u, v):
    return u[0] * v[1] - u[1] * v[0]

def scale(k, u):
    return tuple(k * x for x in u)

A, B, H, C = (-a, zero), (zero, b), (zero, zero), (c, zero)
q = b*b + c*c                  # Strictly positive.
N = (b*b*c, b*c*c)             # D=N/q.

checks = {}

# D=B+t(C-B), where t=c^2/q is strictly between 0 and 1.
checks["D lies on BC"] = norm2(
    sub(N, tuple(q*x + c*c*y for x, y in zip(B, sub(C, B))))
)
checks["HD perpendicular BC"] = dot(N, sub(C, B))

# These are twice the proposed circumcenters.
U1, U2, U3 = (-a, b), (zero, b), (c, zero)

def doubled_distance_squared(U, X):
    return norm2(sub(U, scale(2, X)))

checks["O1 equidistant from A,H"] = (
    doubled_distance_squared(U1, A) - norm2(U1)
)
checks["O1 equidistant from B,H"] = (
    doubled_distance_squared(U1, B) - norm2(U1)
)
checks["O2 equidistant from B,H"] = (
    doubled_distance_squared(U2, B) - norm2(U2)
)
checks["O3 equidistant from C,H"] = (
    doubled_distance_squared(U3, C) - norm2(U3)
)

# Clear q^2 from the squared-distance equalities involving D.
for label, U in (("O2", U2), ("O3", U3)):
    checks[label + " equidistant from D,H"] = (
        norm2(sub(scale(q, U), scale(2, N))) - q*q*norm2(U)
    )

original_det = det(sub(B, A), sub(H, A))
scaled_center_det = det(sub(U2, U1), sub(U3, U1))
checks["scaled center determinant equals original determinant"] = (
    scaled_center_det - original_det
)
checks["original determinant is -ab, hence nonzero"] = original_det + a*b

failed = [name for name, polynomial in checks.items()
          if not polynomial.is_zero()]

if failed:
    print("Failed exact identities:", ", ".join(failed))
    print("CHECK UNKNOWN")
    print("UNSUPPORTED")
else:
    # Scaling all center coordinates by 2 multiplies their area by 4.
    expected = Fraction(1, 4)
    submitted = Fraction(1, 4)
    print("All coordinate and circumcenter identities verified symbolically.")
    print("Area(ABH) = ab/2; area(O1O2O3) = ab/8.")
    print("Universal result for all admissible triangles; not sampling.")
    print("Expected ratio:", expected)
    print("Submitted ratio:", submitted)
    print("CHECK PASS" if expected == submitted else "CHECK FAIL")
